CREATE OR REPLACE FUNCTION app_private.approve_material_po_quality(p_delivery_batch_id uuid, p_wms_transaction_id text, p_actor_user_id uuid, p_quality_result text, p_lines jsonb, p_attachments jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_po_id text;
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_tx public.transactions%rowtype;
  v_line jsonb;
  v_delivery_line public.purchase_order_delivery_lines%rowtype;
  v_delivery_line_id uuid;
  v_item_id text;
  v_delivered_purchase_qty numeric;
  v_accepted_purchase_qty numeric;
  v_delivered_stock_qty numeric;
  v_accepted_stock_qty numeric;
  v_variance_reason text;
  v_seen_line_ids uuid[] := '{}'::uuid[];
  v_expected_line_count integer;
  v_wms_items jsonb := '[]'::jsonb;
  v_gross numeric := 0;
  v_combined_reason text;
  v_stock_factor numeric;
  v_stock_unit_price numeric;
begin
  if p_actor_user_id is null
     or public.current_app_user_id() is null
     or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;
  if p_quality_result not in ('passed', 'partial', 'rejected') then
    raise exception 'Kết quả kiểm tra SL/CL không hợp lệ.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_attachments, '[]'::jsonb)) <> 'array' then
    raise exception 'Dữ liệu nhận hàng không hợp lệ.' using errcode = '22023';
  end if;

  select batch.purchase_order_id into v_po_id
  from public.purchase_order_delivery_batches batch
  where batch.id = p_delivery_batch_id;
  if not found then
    raise exception 'Không tìm thấy đợt giao.' using errcode = '22023';
  end if;

  perform 1 from public.purchase_orders where id = v_po_id for update;
  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if v_batch.wms_transaction_id is distinct from p_wms_transaction_id
     or v_batch.status <> 'receiving' then
    raise exception 'Đợt giao không còn ở trạng thái chờ duyệt SL/CL.' using errcode = '22023';
  end if;

  select * into v_tx
  from public.transactions
  where id = p_wms_transaction_id
  for update;
  if not found
     or v_tx.source_type <> 'po_delivery_batch'
     or v_tx.source_id <> p_delivery_batch_id::text then
    raise exception 'WMS không liên kết đúng đợt giao.' using errcode = '22023';
  end if;
  if v_tx.status <> 'PENDING'::public.transaction_status then
    raise exception 'Phiếu WMS không còn chờ duyệt SL/CL.' using errcode = '22023';
  end if;
  if not app_private.current_user_can_receive_purchase_batch_v2(
    p_actor_user_id,
    v_tx.target_warehouse_id
  ) then
    raise exception 'Người dùng không có quyền duyệt SL/CL tại kho nhận.' using errcode = '42501';
  end if;

  select count(*) into v_expected_line_count
  from public.purchase_order_delivery_lines
  where delivery_batch_id = p_delivery_batch_id;
  if v_expected_line_count = 0
     or jsonb_array_length(p_lines) <> v_expected_line_count then
    raise exception 'Payload nhận hàng phải khớp 1-1 với dòng đợt giao.' using errcode = '22023';
  end if;

  for v_line in
    select value from jsonb_array_elements(p_lines) line(value)
  loop
    v_delivery_line_id := nullif(coalesce(
      v_line ->> 'deliveryLineId', v_line ->> 'delivery_line_id'
    ), '')::uuid;
    v_item_id := nullif(coalesce(v_line ->> 'itemId', v_line ->> 'item_id'), '');
    v_accepted_purchase_qty := coalesce(nullif(coalesce(
      v_line ->> 'acceptedPurchaseQty', v_line ->> 'accepted_purchase_qty'
    ), '')::numeric, 0);
    v_delivered_purchase_qty := coalesce(nullif(coalesce(
      v_line ->> 'deliveredPurchaseQty', v_line ->> 'delivered_purchase_qty'
    ), '')::numeric, v_accepted_purchase_qty);
    v_accepted_stock_qty := coalesce(nullif(coalesce(
      v_line ->> 'acceptedStockQty', v_line ->> 'accepted_stock_qty'
    ), '')::numeric, 0);
    v_delivered_stock_qty := coalesce(nullif(coalesce(
      v_line ->> 'deliveredStockQty', v_line ->> 'delivered_stock_qty'
    ), '')::numeric, v_accepted_stock_qty);
    v_variance_reason := nullif(trim(coalesce(
      v_line ->> 'varianceReason', v_line ->> 'variance_reason', ''
    )), '');

    if v_delivery_line_id is null or v_item_id is null then
      raise exception 'Dòng nhận hàng thiếu deliveryLineId hoặc itemId.' using errcode = '22023';
    end if;
    if v_delivery_line_id = any(v_seen_line_ids) then
      raise exception 'Dòng nhận hàng bị lặp.' using errcode = '22023';
    end if;
    if v_delivered_purchase_qty < 0
       or v_accepted_purchase_qty < 0
       or v_delivered_stock_qty < 0
       or v_accepted_stock_qty < 0 then
      raise exception 'Số lượng thực tế không được âm.' using errcode = '22023';
    end if;
    if v_accepted_purchase_qty > v_delivered_purchase_qty then
      raise exception 'Số chấp nhận không được lớn hơn số giao thực tế.' using errcode = '22023';
    end if;
    if v_accepted_stock_qty > v_delivered_stock_qty then
      raise exception 'Số nhập kho không được lớn hơn số giao theo đơn vị tồn kho.' using errcode = '22023';
    end if;

    select * into v_delivery_line
    from public.purchase_order_delivery_lines
    where id = v_delivery_line_id
      and delivery_batch_id = p_delivery_batch_id
    for update;
    if not found or v_delivery_line.item_id <> v_item_id then
      raise exception 'Dòng nhận hàng không thuộc đợt giao.' using errcode = '22023';
    end if;

    if (
      v_delivered_purchase_qty is distinct from coalesce(v_delivery_line.planned_qty, 0)
      or v_accepted_purchase_qty is distinct from v_delivered_purchase_qty
      or v_accepted_stock_qty is distinct from v_delivered_stock_qty
    ) and v_variance_reason is null then
      raise exception 'Phải nhập lý do khi số đặt, giao hoặc chấp nhận chênh lệch.' using errcode = '22023';
    end if;

    update public.purchase_order_delivery_lines
    set delivered_qty = v_delivered_purchase_qty,
        accepted_qty = v_accepted_purchase_qty,
        delivered_stock_qty = v_delivered_stock_qty,
        accepted_stock_qty = v_accepted_stock_qty,
        updated_at = now()
    where id = v_delivery_line.id;

    v_seen_line_ids := array_append(v_seen_line_ids, v_delivery_line.id);
    if v_variance_reason is not null then
      v_combined_reason := concat_ws('; ', v_combined_reason, v_variance_reason);
    end if;
    v_stock_factor := case
      when coalesce(v_delivery_line.planned_qty, 0) > 0
        and coalesce(v_delivery_line.stock_planned_qty, 0) > 0 then
          v_delivery_line.stock_planned_qty / v_delivery_line.planned_qty
      else 1
    end;
    v_stock_unit_price := case
      when v_stock_factor > 0 then coalesce(v_delivery_line.delivery_unit_price, 0) / v_stock_factor
      else coalesce(v_delivery_line.delivery_unit_price, 0)
    end;
    v_gross := v_gross
      + v_accepted_purchase_qty
      * coalesce(v_delivery_line.delivery_unit_price, 0)
      * (1 + coalesce(v_batch.vat_rate, 0) / 100);

    v_wms_items := v_wms_items || jsonb_build_array(jsonb_build_object(
      'itemId', v_delivery_line.item_id,
      'quantity', v_accepted_stock_qty,
      'orderedQty', coalesce(v_delivery_line.stock_planned_qty, v_delivery_line.planned_qty, 0),
      'deliveredStockQty', v_delivered_stock_qty,
      'price', v_stock_unit_price,
      'accountingQty', v_accepted_purchase_qty,
      'orderedPurchaseQty', v_delivery_line.planned_qty,
      'deliveredPurchaseQty', v_delivered_purchase_qty,
      'accountingUnit', coalesce(v_delivery_line.unit, v_delivery_line.stock_unit, ''),
      'accountingPrice', coalesce(v_delivery_line.delivery_unit_price, 0),
      'varianceQty', v_accepted_purchase_qty - coalesce(v_delivery_line.planned_qty, 0),
      'varianceReason', v_variance_reason,
      'purchaseOrderLineId', v_delivery_line.purchase_order_line_id,
      'purchaseOrderDeliveryBatchId', p_delivery_batch_id,
      'purchaseOrderDeliveryLineId', v_delivery_line.id,
      'fulfillmentMode', coalesce(v_batch.fulfillment_mode, 'RECEIVE_TO_STOCK')
    ));
  end loop;

  if coalesce(array_length(v_seen_line_ids, 1), 0) <> v_expected_line_count then
    raise exception 'Payload nhận hàng thiếu dòng đợt giao.' using errcode = '22023';
  end if;

  update public.transactions
  set items = v_wms_items,
      attachments = coalesce(p_attachments, '[]'::jsonb),
      status = 'APPROVED'::public.transaction_status,
      approver_id = p_actor_user_id,
      approved_at = now()
  where id = p_wms_transaction_id;

  update public.purchase_order_delivery_batches
  set status = 'quality_approved',
      quality_result = p_quality_result,
      variance_reason = v_combined_reason,
      quality_approved_by = p_actor_user_id,
      quality_approved_at = now(),
      accepted_gross_amount = round(v_gross, 2),
      updated_at = now()
  where id = p_delivery_batch_id;

  return app_private.purchase_receipt_command_result_v2(p_delivery_batch_id, false);
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_material_po_receipt(p_delivery_batch_id uuid, p_wms_transaction_id text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid;
  v_result jsonb;
  v_po_id text;
  v_purchase_mode text;
  v_previous_guard text;
begin
  v_actor := app_private.require_purchase_receipt_stage_action(
    p_wms_transaction_id,
    p_actor_user_id,
    'wms.transaction.complete'
  );

  v_result := app_private.finalize_purchase_receipt_v2(
    p_delivery_batch_id,
    p_wms_transaction_id,
    v_actor
  );

  select batch.purchase_order_id, po.purchase_mode
  into v_po_id, v_purchase_mode
  from public.purchase_order_delivery_batches batch
  join public.purchase_orders po on po.id = batch.purchase_order_id
  where batch.id = p_delivery_batch_id;

  if coalesce(v_purchase_mode, 'single') = 'single'
     and v_result ->> 'transactionStatus' = 'COMPLETED' then
    v_previous_guard := current_setting('app.material_transition_context', true);
    perform set_config('app.material_transition_context', 'on', true);
    update public.purchase_orders
    set status = 'delivered',
        actual_delivery_date = coalesce(actual_delivery_date, current_date::text)
    where id = v_po_id;
    perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
    v_result := v_result || jsonb_build_object('purchaseOrderStatus', 'delivered');
  else
    v_result := v_result || jsonb_build_object(
      'purchaseOrderStatus', (select status from public.purchase_orders where id = v_po_id)
    );
  end if;

  return v_result;
exception
  when others then
    perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
    raise;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.post_inventory_ledger_entry(p_inventory_transaction_id uuid, p_entry_no integer, p_document_code text, p_transaction_date timestamp with time zone, p_transaction_type text, p_direction text, p_material_id text, p_warehouse_id text, p_project_id text, p_construction_site_id text, p_source_type text, p_source_id text, p_source_code text, p_source_line_id text, p_related_request_id text, p_qty numeric, p_unit_price numeric, p_description text, p_metadata jsonb, p_created_by uuid, p_approved_by uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry_id uuid := gen_random_uuid();
  v_delta numeric;
  v_value_delta numeric;
  v_balance_after_qty numeric;
  v_balance_after_value numeric;
  v_unit text;
begin
  if p_qty is null or p_qty <= 0 then
    raise exception 'ledger quantity must be positive';
  end if;
  if nullif(p_material_id, '') is null then
    raise exception 'material id is required';
  end if;
  if nullif(p_warehouse_id, '') is null then
    raise exception 'warehouse id is required';
  end if;

  select i.unit into v_unit
  from public.items i
  where i.id = p_material_id;

  v_unit := coalesce(
    v_unit,
    nullif(p_metadata->>'unit', ''),
    nullif(p_metadata->>'unitSnapshot', ''),
    nullif(p_metadata->>'accountingUnit', '')
  );

  v_delta := case when p_direction = 'in' then p_qty else -p_qty end;
  v_value_delta := v_delta * coalesce(p_unit_price, 0);

  insert into public.inventory_balances (
    material_id, warehouse_id, project_id, construction_site_id,
    on_hand_qty, total_value, average_unit_cost,
    last_ledger_entry_id, last_transaction_date, updated_at
  )
  values (
    p_material_id, p_warehouse_id, nullif(p_project_id, ''), nullif(p_construction_site_id, ''),
    v_delta, v_value_delta,
    case when v_delta = 0 then 0 else coalesce(p_unit_price, 0) end,
    v_entry_id, p_transaction_date, now()
  )
  on conflict (material_id, warehouse_id, scope_key)
  do update set
    on_hand_qty = public.inventory_balances.on_hand_qty + excluded.on_hand_qty,
    total_value = public.inventory_balances.total_value + excluded.total_value,
    average_unit_cost = case
      when (public.inventory_balances.on_hand_qty + excluded.on_hand_qty) = 0 then 0
      else (public.inventory_balances.total_value + excluded.total_value)
        / nullif(public.inventory_balances.on_hand_qty + excluded.on_hand_qty, 0)
    end,
    last_ledger_entry_id = excluded.last_ledger_entry_id,
    last_transaction_date = excluded.last_transaction_date,
    updated_at = now()
  returning on_hand_qty, total_value
    into v_balance_after_qty, v_balance_after_value;

  insert into public.inventory_ledger_entries (
    id, inventory_transaction_id, entry_no, document_code,
    transaction_date, transaction_type, movement_direction,
    material_id, warehouse_id, project_id, construction_site_id,
    source_type, source_id, source_code, source_line_id, related_request_id,
    quantity_in, quantity_out, unit, unit_price,
    balance_after_qty, balance_after_value,
    description, metadata, created_by, approved_by
  )
  values (
    v_entry_id, p_inventory_transaction_id, p_entry_no, p_document_code,
    p_transaction_date, p_transaction_type, p_direction,
    p_material_id, p_warehouse_id, nullif(p_project_id, ''), nullif(p_construction_site_id, ''),
    p_source_type, p_source_id, p_source_code, nullif(p_source_line_id, ''), nullif(p_related_request_id, ''),
    case when p_direction = 'in' then p_qty else 0 end,
    case when p_direction = 'out' then p_qty else 0 end,
    v_unit, coalesce(p_unit_price, 0),
    v_balance_after_qty, v_balance_after_value,
    p_description, coalesce(p_metadata, '{}'::jsonb), p_created_by, p_approved_by
  );

  return v_entry_id;
end;
$function$

CREATE OR REPLACE FUNCTION app_private.record_supplier_invoice_reconciliation_v2(p_invoice jsonb, p_links jsonb, p_actor_user_id uuid)
 RETURNS supplier_invoices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_invoice public.supplier_invoices%rowtype;
  v_invoice_id uuid := coalesce(nullif(p_invoice ->> 'id', '')::uuid, gen_random_uuid());
  v_supplier_id text := nullif(trim(coalesce(p_invoice ->> 'supplierId', p_invoice ->> 'supplier_id')), '');
  v_supplier_name text := nullif(trim(coalesce(p_invoice ->> 'supplierNameSnapshot', p_invoice ->> 'supplier_name_snapshot')), '');
  v_invoice_number text := nullif(trim(coalesce(p_invoice ->> 'invoiceNumber', p_invoice ->> 'invoice_number')), '');
  v_invoice_date date := nullif(coalesce(p_invoice ->> 'invoiceDate', p_invoice ->> 'invoice_date'), '')::date;
  v_net_amount numeric(18,2) := round(coalesce(nullif(coalesce(p_invoice ->> 'netAmount', p_invoice ->> 'net_amount'), '')::numeric, 0), 2);
  v_vat_amount numeric(18,2) := round(coalesce(nullif(coalesce(p_invoice ->> 'vatAmount', p_invoice ->> 'vat_amount'), '')::numeric, 0), 2);
  v_gross_amount numeric(18,2) := round(coalesce(nullif(coalesce(p_invoice ->> 'grossAmount', p_invoice ->> 'gross_amount'), '')::numeric, 0), 2);
  v_variance_reason text := nullif(trim(coalesce(p_invoice ->> 'varianceReason', p_invoice ->> 'variance_reason', '')), '');
  v_attachments jsonb := coalesce(p_invoice -> 'attachments', '[]'::jsonb);
  v_link jsonb;
  v_payable_id uuid;
  v_allocated numeric(18,2);
  v_allocated_total numeric(18,2) := 0;
  v_estimated_total numeric(18,2) := 0;
  v_variance numeric(18,2);
  v_ap public.supplier_payable_documents%rowtype;
  v_project_id text := null;
  v_site_id text := null;
  v_project_finance_id text := null;
  v_adjustment_ref text;
  v_adjustment_id text;
begin
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thao tac khong hop le.' using errcode = '42501';
  end if;
  if v_supplier_id is null or v_supplier_name is null or v_invoice_number is null then
    raise exception 'Hoa don thieu NCC hoac so hoa don.' using errcode = '22023';
  end if;
  if v_gross_amount <= 0 or v_net_amount < 0 or v_vat_amount < 0 then
    raise exception 'Gia tri hoa don khong hop le.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_links, '[]'::jsonb)) <> 'array' or jsonb_array_length(p_links) = 0 then
    raise exception 'Hoa don phai link it nhat mot AP.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_attachments) <> 'array' then
    raise exception 'Dinh kem hoa don phai la mang JSON.' using errcode = '22023';
  end if;

  for v_link in select value from jsonb_array_elements(p_links) as link(value)
  loop
    v_payable_id := nullif(coalesce(v_link ->> 'payableDocumentId', v_link ->> 'payable_document_id'), '')::uuid;
    v_allocated := round(coalesce(nullif(coalesce(v_link ->> 'allocatedGrossAmount', v_link ->> 'allocated_gross_amount'), '')::numeric, 0), 2);
    if v_payable_id is null or v_allocated <= 0 then
      raise exception 'Link AP hoa don khong hop le.' using errcode = '22023';
    end if;

    select * into v_ap
    from public.supplier_payable_documents
    where id = v_payable_id
    for update;
    if not found then
      raise exception 'Khong tim thay AP %.', v_payable_id using errcode = '22023';
    end if;
    if coalesce(v_ap.supplier_id, '') <> v_supplier_id then
      raise exception 'Tat ca AP duoc link phai cung nha cung cap voi hoa don.' using errcode = '22023';
    end if;
    if not app_private.ap_scope_can_mutate(v_ap.project_id, v_ap.construction_site_id) then
      raise exception 'Nguoi dung khong co quyen doi soat AP.' using errcode = '42501';
    end if;
    if v_project_id is null and v_site_id is null then
      v_project_id := v_ap.project_id;
      v_site_id := v_ap.construction_site_id;
    end if;

    v_allocated_total := round(v_allocated_total + v_allocated, 2);
    v_estimated_total := round(v_estimated_total + greatest(coalesce(v_ap.recognized_amount, 0) - coalesce(v_ap.credit_amount, 0), 0), 2);
  end loop;

  if v_allocated_total <> v_gross_amount then
    raise exception 'Tong phan bo AP phai bang tong tien hoa don.' using errcode = '22023';
  end if;

  v_variance := round(v_gross_amount - v_estimated_total, 2);
  if v_variance <> 0 and v_variance_reason is null then
    raise exception 'Hoa don lech AP phai co ly do chenh lech.' using errcode = '22023';
  end if;

  insert into public.supplier_invoices (
    id, supplier_id, supplier_name_snapshot, invoice_number, invoice_date,
    net_amount, vat_amount, gross_amount, variance_reason, attachments, created_by
  )
  values (
    v_invoice_id, v_supplier_id, v_supplier_name, v_invoice_number, v_invoice_date,
    v_net_amount, v_vat_amount, v_gross_amount, v_variance_reason, v_attachments, p_actor_user_id
  )
  returning * into v_invoice;

  for v_link in select value from jsonb_array_elements(p_links) as link(value)
  loop
    v_payable_id := nullif(coalesce(v_link ->> 'payableDocumentId', v_link ->> 'payable_document_id'), '')::uuid;
    v_allocated := round(coalesce(nullif(coalesce(v_link ->> 'allocatedGrossAmount', v_link ->> 'allocated_gross_amount'), '')::numeric, 0), 2);

    insert into public.supplier_invoice_payable_links (
      invoice_id, payable_document_id, allocated_gross_amount
    ) values (
      v_invoice_id, v_payable_id, v_allocated
    );

    update public.supplier_payable_documents
    set invoice_number = v_invoice_number,
        invoice_date = v_invoice_date,
        metadata = coalesce(metadata, '{}'::jsonb)
          || jsonb_build_object('supplierInvoiceId', v_invoice_id, 'supplierInvoiceNumber', v_invoice_number),
        updated_at = now()
    where id = v_payable_id;
  end loop;

  if v_variance <> 0 then
    select id into v_project_finance_id
    from public.project_finances
    where (v_project_id is not null and project_id = v_project_id)
       or (v_site_id is not null and construction_site_id = v_site_id)
    limit 1;

    v_adjustment_ref := 'supplier_invoice_adjustment:' || v_invoice_id::text;
    v_adjustment_id := 'supplier-invoice-adjustment-' || v_invoice_id::text;

    insert into public.project_transactions (
      id, "projectFinanceId", "constructionSiteId",
      project_id, project_finance_id, construction_site_id,
      type, category, amount, description, date, source,
      "sourceRef", source_ref, contract_cost_item_id,
      cost_classification_status, counterparty_partner_id,
      counterparty_name, attachments, "createdBy", "createdAt"
    )
    values (
      v_adjustment_id,
      coalesce(v_project_finance_id, ''),
      coalesce(v_site_id, ''),
      v_project_id,
      nullif(v_project_finance_id, ''),
      v_site_id,
      'expense',
      'materials',
      v_variance,
      'Chênh lệch hóa đơn NCC ' || v_invoice_number,
      v_invoice_date::text,
      'workflow',
      v_adjustment_ref,
      v_adjustment_ref,
      null,
      'auto',
      null,
      v_supplier_name,
      v_attachments,
      p_actor_user_id::text,
      now()
    )
    on conflict (source_ref) do nothing;

    insert into public.supplier_payable_documents (
      code, source_type, source_id, project_id, construction_site_id,
      supplier_id, supplier_name_snapshot, document_no, document_date, due_date,
      committed_amount, recognized_amount, credit_amount, status, qr_token,
      invoice_number, invoice_date, metadata, created_by
    )
    values (
      'AP-INV-ADJ-' || replace(v_invoice_id::text, '-', ''),
      'supplier_invoice_adjustment',
      v_invoice_id::text,
      v_project_id,
      v_site_id,
      v_supplier_id,
      v_supplier_name,
      v_invoice_number || '-ADJ',
      v_invoice_date,
      null,
      abs(v_variance),
      greatest(v_variance, 0),
      greatest(-v_variance, 0),
      case when v_variance > 0 then 'open' else 'paid' end,
      'ap_invoice_adj_' || replace(v_invoice_id::text, '-', ''),
      v_invoice_number,
      v_invoice_date,
      jsonb_build_object(
        'supplierInvoiceId', v_invoice_id,
        'supplierInvoiceNumber', v_invoice_number,
        'sourceRef', v_adjustment_ref,
        'varianceAmount', v_variance,
        'varianceReason', v_variance_reason
      ),
      p_actor_user_id
    )
    on conflict (source_type, source_id) do nothing;
  end if;

  if to_regclass('public.project_document_links') is not null then
    for v_link in select value from jsonb_array_elements(p_links) as link(value)
    loop
      v_payable_id := nullif(coalesce(v_link ->> 'payableDocumentId', v_link ->> 'payable_document_id'), '')::uuid;
      v_allocated := round(coalesce(nullif(coalesce(v_link ->> 'allocatedGrossAmount', v_link ->> 'allocated_gross_amount'), '')::numeric, 0), 2);
      insert into public.project_document_links (
        source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata
      )
      values (
        'supplier_payable_document', v_payable_id::text,
        'supplier_invoice', v_invoice_id::text,
        v_project_id,
        'invoiced_by',
        'active',
        jsonb_build_object('allocatedGrossAmount', v_allocated)
      )
      on conflict (source_type, source_id, target_type, target_id, relation_type) do update
      set status = excluded.status,
          metadata = coalesce(public.project_document_links.metadata, '{}'::jsonb) || excluded.metadata,
          updated_at = now();
    end loop;

    if v_variance <> 0 then
      insert into public.project_document_links (
        source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata
      )
      values (
        'supplier_invoice', v_invoice_id::text,
        'supplier_payable_document',
        (select id::text from public.supplier_payable_documents
         where source_type = 'supplier_invoice_adjustment' and source_id = v_invoice_id::text limit 1),
        v_project_id,
        'adjusts_ap',
        'active',
        jsonb_build_object('varianceAmount', v_variance)
      )
      on conflict (source_type, source_id, target_type, target_id, relation_type) do update
      set status = excluded.status,
          metadata = coalesce(public.project_document_links.metadata, '{}'::jsonb) || excluded.metadata,
          updated_at = now();

      insert into public.project_document_links (
        source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata
      )
      values (
        'supplier_invoice', v_invoice_id::text,
        'project_transaction', v_adjustment_id,
        v_project_id,
        'adjusts_cost',
        'active',
        jsonb_build_object('varianceAmount', v_variance)
      )
      on conflict (source_type, source_id, target_type, target_id, relation_type) do update
      set status = excluded.status,
          metadata = coalesce(public.project_document_links.metadata, '{}'::jsonb) || excluded.metadata,
          updated_at = now();
    end if;
  end if;

  return v_invoice;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_fulfillment_receipt_for_transaction(p_transaction_id text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'app_private'
AS $function$
declare
  v_tx public.transactions%rowtype;
  v_user public.users%rowtype;
  v_batch public.material_request_fulfillment_batches%rowtype;
  v_actor_user_id uuid;
  v_can_sync boolean := false;
  v_line record;
  v_received_qty numeric;
  v_reason text;
  v_has_variance boolean := false;
  v_po_id text;
  v_po public.purchase_orders%rowtype;
  v_next_items jsonb;
  v_is_delivered boolean;
  v_already_recorded boolean;
begin
  select * into v_tx
  from public.transactions
  where id = p_transaction_id
  for update;
  if not found then
    raise exception 'transaction not found: %', p_transaction_id;
  end if;

  select * into v_user
  from public.users
  where id = public.current_app_user_id();
  if v_user.id is null then
    raise exception 'authentication required';
  end if;

  if p_actor_user_id is not null and p_actor_user_id is distinct from v_user.id then
    raise exception 'actor user id must match the authenticated user'
      using errcode = '42501';
  end if;
  v_actor_user_id := v_user.id;

  v_can_sync := app_private.wms_transaction_has_action(
    'wms.transaction.complete', v_tx.type,
    v_tx.source_warehouse_id, v_tx.target_warehouse_id, v_tx.items,
    v_tx.requester_id, v_tx.approver_id, v_user.id
  );

  if not v_can_sync then
    raise exception 'insufficient privilege to sync fulfillment receipt'
      using errcode = '42501';
  end if;

  if v_tx.status <> 'COMPLETED'::public.transaction_status then
    raise exception 'Chỉ đồng bộ nhận hàng cho phiếu kho đã hoàn tất.';
  end if;

  select * into v_batch
  from public.material_request_fulfillment_batches
  where transaction_id = p_transaction_id
  for update;
  if not found then
    return jsonb_build_object('synced', false, 'reason', 'batch_not_found');
  end if;

  if v_batch.status not in ('issued', 'received') then
    return jsonb_build_object('synced', false, 'reason', 'batch_not_receivable', 'batchStatus', v_batch.status);
  end if;

  for v_line in
    select *
    from public.material_request_fulfillment_lines
    where batch_id = v_batch.id
    order by created_at asc
    for update
  loop
    select
      coalesce(sum(coalesce(nullif(item.value->>'quantity', '')::numeric, 0)), 0),
      max(nullif(item.value->>'varianceReason', ''))
    into v_received_qty, v_reason
    from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) item(value)
    where coalesce(item.value->>'fulfillmentBatchId', '') = v_batch.id::text
      and item.value->>'requestLineId' = v_line.request_line_id;

    if coalesce(v_received_qty, 0) = 0 then
      select
        coalesce(sum(coalesce(nullif(item.value->>'quantity', '')::numeric, 0)), 0),
        max(nullif(item.value->>'varianceReason', ''))
      into v_received_qty, v_reason
      from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) item(value)
      where coalesce(item.value->>'fulfillmentBatchId', '') = v_batch.id::text
        and item.value->>'itemId' = v_line.item_id;
    end if;

    if coalesce(v_received_qty, 0) <> coalesce(v_line.issued_qty, 0) then
      v_has_variance := true;
    end if;

    update public.material_request_fulfillment_lines
    set
      received_qty = coalesce(v_received_qty, 0),
      variance_reason = coalesce(
        nullif(v_reason, ''),
        variance_reason,
        case
          when coalesce(v_received_qty, 0) <> coalesce(v_line.issued_qty, 0)
            then 'Thủ kho công trường xác nhận số lượng thực nhận lệch phiếu kho.'
          else null
        end
      )
    where id = v_line.id;
  end loop;

  if v_batch.status = 'issued' then
    update public.material_request_fulfillment_batches
    set
      status = 'received',
      received_by = v_actor_user_id,
      received_at = now(),
      reason = coalesce(
        reason,
        case when v_has_variance then 'Thủ kho công trường xác nhận nhận lệch theo thực tế.' else null end
      )
    where id = v_batch.id
    returning * into v_batch;
  end if;

  for v_po_id in
    select distinct po_id
    from public.material_request_fulfillment_lines
    where batch_id = v_batch.id
      and po_id is not null
  loop
    select * into v_po
    from public.purchase_orders
    where id = v_po_id
    for update;
    if not found then continue; end if;

    select exists (
      select 1
      from jsonb_array_elements_text(coalesce(v_po.received_transaction_ids, '[]'::jsonb)) existing(id)
      where existing.id = v_tx.id
    ) into v_already_recorded;
    if v_already_recorded then continue; end if;

    with receipt_by_line as (
      select po_line_id, sum(coalesce(received_qty, 0)) as received_qty
      from public.material_request_fulfillment_lines
      where batch_id = v_batch.id
        and po_id = v_po_id
        and po_line_id is not null
      group by po_line_id
    ),
    item_rows as (
      select
        item.value as item,
        item.ordinality,
        coalesce(item.value->>'lineId', item.value->>'line_id', item.value->>'itemId', item.value->>'item_id') as line_key,
        coalesce(nullif(item.value->>'qty', '')::numeric, 0) as ordered_qty,
        coalesce(nullif(item.value->>'receivedQty', '')::numeric, 0) as current_received_qty
      from jsonb_array_elements(coalesce(v_po.items, '[]'::jsonb)) with ordinality item(value, ordinality)
    ),
    next_rows as (
      select
        case
          when coalesce(r.received_qty, 0) > 0 then
            jsonb_set(
              ir.item,
              '{receivedQty}',
              to_jsonb(ir.current_received_qty + coalesce(r.received_qty, 0)),
              true
            )
          else ir.item
        end as item,
        ir.ordinality
      from item_rows ir
      left join receipt_by_line r on r.po_line_id = ir.line_key
    )
    select coalesce(jsonb_agg(item order by ordinality), '[]'::jsonb)
    into v_next_items
    from next_rows;

    select coalesce(bool_and(
      coalesce(nullif(item.value->>'qty', '')::numeric, 0) <= coalesce(nullif(item.value->>'receivedQty', '')::numeric, 0)
    ), false)
    into v_is_delivered
    from jsonb_array_elements(coalesce(v_next_items, '[]'::jsonb)) item(value);

    update public.purchase_orders
    set
      items = v_next_items,
      status = case when v_is_delivered then 'delivered' else 'partial' end,
      actual_delivery_date = case when v_is_delivered then current_date::text else actual_delivery_date end,
      received_transaction_ids = coalesce(received_transaction_ids, '[]'::jsonb) || jsonb_build_array(v_tx.id)
    where id = v_po_id;
  end loop;

  perform app_private.sync_po_delivery_schedule_status_v1(v_batch.po_delivery_batch_id, v_batch.po_delivery_group_id);
  perform app_private.sync_material_request_receipt_status_v1(
    v_batch.material_request_id,
    v_actor_user_id,
    'Đồng bộ sau khi phiếu kho hoàn tất'
  );

  return jsonb_build_object(
    'synced', true,
    'batchId', v_batch.id,
    'batchStatus', v_batch.status,
    'hasVariance', v_has_variance
  );
end;
$function$

CREATE OR REPLACE FUNCTION app_private.sync_wms_transaction_to_inventory_ledger(p_transaction_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tx public.transactions%rowtype;
  v_existing_id uuid;
  v_original_inventory_transaction public.inventory_transactions%rowtype;
  v_inventory_transaction_id uuid;
  v_code text;
  v_line jsonb;
  v_entry_no integer := 0;
  v_tx_date timestamptz;
  v_item_id text;
  v_qty numeric;
  v_price numeric;
  v_source_line_id text;
  v_scope record;
  v_metadata jsonb;
begin
  select * into v_tx
  from public.transactions
  where id = p_transaction_id
  for update;
  if not found then raise exception 'transaction not found: %', p_transaction_id; end if;
  if v_tx.status::text <> 'COMPLETED' then return null; end if;
  if coalesce(v_tx.business_event_type, '') <> 'reversal' then
    return app_private.sync_wms_transaction_to_inventory_ledger_pre_reversal_20260905(
      p_transaction_id
    );
  end if;

  select id into v_existing_id
  from public.inventory_transactions
  where source_type = 'wms_transaction' and source_id = v_tx.id
  limit 1;
  if v_existing_id is not null then return v_existing_id; end if;

  if v_tx.type::text <> 'IMPORT'
     or nullif(v_tx.reversal_of_transaction_id, '') is null then
    raise exception 'Chứng từ đảo phải là IMPORT và liên kết phiếu WMS gốc.';
  end if;

  select original.* into v_original_inventory_transaction
  from public.inventory_transactions original
  where original.source_type = 'wms_transaction'
    and original.source_id = v_tx.reversal_of_transaction_id
  order by original.created_at
  limit 1
  for update;
  if not found then
    raise exception 'Không tìm thấy inventory transaction gốc để ghi đảo.';
  end if;
  if v_original_inventory_transaction.status <> 'posted' then
    raise exception 'Inventory transaction gốc không còn ở trạng thái posted.';
  end if;

  v_code := app_private.next_inventory_ledger_code('in');
  v_tx_date := coalesce(nullif(v_tx.date::text, '')::timestamptz, now());
  select * into v_scope
  from app_private.resolve_warehouse_project_scope(v_tx.target_warehouse_id);
  v_metadata := jsonb_build_object(
    'wmsTransactionId', v_tx.id,
    'reversalOfTransactionId', v_tx.reversal_of_transaction_id,
    'reversalOfInventoryTransactionId', v_original_inventory_transaction.id,
    'businessEventType', 'reversal',
    'businessEventReason', v_tx.business_event_reason,
    'targetWarehouseId', v_tx.target_warehouse_id,
    'items', coalesce(v_tx.items, '[]'::jsonb)
  );

  insert into public.inventory_transactions(
    code, transaction_type, status, transaction_date,
    source_type, source_id, source_code, related_request_id,
    project_id, construction_site_id, business_event_type,
    description, metadata, created_by, approved_by, posted_at,
    reversal_of_inventory_transaction_id
  ) values (
    v_code, 'reversal', 'posted', v_tx_date,
    'wms_transaction', v_tx.id, v_tx.id, v_tx.related_request_id,
    v_scope.project_id, v_scope.construction_site_id, 'reversal',
    v_tx.note, v_metadata, v_tx.requester_id, v_tx.approver_id, now(),
    v_original_inventory_transaction.id
  ) returning id into v_inventory_transaction_id;

  for v_line in select value from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb))
  loop
    v_item_id := v_line ->> 'itemId';
    v_qty := coalesce(nullif(v_line ->> 'quantity', '')::numeric, 0);
    v_price := coalesce(nullif(v_line ->> 'price', '')::numeric, 0);
    v_source_line_id := nullif(coalesce(
      v_line ->> 'materialIssueLineId',
      v_line ->> 'requestLineId',
      v_line ->> 'lineId'
    ), '');
    if v_item_id is null or v_qty <= 0 then
      raise exception 'invalid reversal transaction item payload';
    end if;
    v_entry_no := v_entry_no + 1;
    perform app_private.post_inventory_ledger_entry(
      v_inventory_transaction_id, v_entry_no, v_code, v_tx_date,
      'reversal', 'in', v_item_id, v_tx.target_warehouse_id,
      v_scope.project_id, v_scope.construction_site_id,
      'wms_transaction', v_tx.id, v_tx.id, v_source_line_id,
      v_tx.related_request_id, v_qty, v_price, v_tx.note,
      v_line || jsonb_build_object(
        'businessEventType', 'reversal',
        'reversalOfTransactionId', v_tx.reversal_of_transaction_id,
        'reversalOfInventoryTransactionId', v_original_inventory_transaction.id
      ),
      v_tx.requester_id, v_tx.approver_id
    );
  end loop;

  update public.inventory_transactions
  set status = 'reversed', reversed_at = now()
  where id = v_original_inventory_transaction.id;

  return v_inventory_transaction_id;
end;
$function$
